import java.util.Locale;

public class CaseConversion {
    public static void main(String[] args) {
        String mixed = "Hello, Java World!";

        System.out.println(mixed.toUpperCase()); // HELLO, JAVA WORLD!
        System.out.println(mixed.toLowerCase()); // hello, java world!

        // Title-case each word
        String[] words = "hello world".split(" ");
        StringBuilder sb = new StringBuilder();
        for (String word : words) {
            if (!word.isEmpty()) {
                sb.append(Character.toUpperCase(word.charAt(0)))
                  .append(word.substring(1).toLowerCase())
                  .append(' ');
            }
        }
        System.out.println(sb.toString().trim()); // Hello World

        String tricky = "istanbul";
        System.out.println(tricky.toUpperCase(new Locale("tr")));  // İSTANBUL (dotted I)
        System.out.println(tricky.toUpperCase(Locale.ROOT));       // ISTANBUL  (safe)
    }
}

