import java.util.Arrays;

public class StringSplitting {
    public static void main(String[] args) {
        String csv = "apple,banana,,cherry,";

        // Default: trailing empty strings removed
        String[] parts = csv.split(",");
        System.out.println(parts.length);          // 4 (trailing empty dropped)
        System.out.println(Arrays.toString(parts)); // [apple, banana, , cherry]

        // -1 keeps all tokens including trailing empty
        String[] allParts = csv.split(",", -1);
        System.out.println(allParts.length);           // 5
        System.out.println(Arrays.toString(allParts)); // [apple, banana, , cherry, ]

        // Limit 3
        String[] limited = csv.split(",", 3);
        System.out.println(Arrays.toString(limited)); // [apple, banana, ,cherry,]

        // Split on whitespace
        String words = "one   two\tthree\nfour";
        System.out.println(Arrays.toString(words.split("\\s+"))); // [one, two, three, four]

        // Split IP — must escape dot!
        String ip = "192.168.1.1";
        System.out.println(Arrays.toString(ip.split("\\.")));  // [192, 168, 1, 1]
        // Wrong: ip.split(".") would split on any char
        System.out.println(Arrays.toString(ip.split(".")));    // [] — every char matches
    }
}

