public class StringBuilderPerformance {

    static String buildSlow(int n) {
        String result = "";
        for (int i = 0; i < n; i++) {
            result += i; // creates a new String each iteration!
            if (i < n - 1) result += ",";
        }
        return result;
    }

    static String buildFast(int n) {
        StringBuilder sb = new StringBuilder(n * 4); // pre-size hint
        for (int i = 0; i < n; i++) {
            sb.append(i);
            if (i < n - 1) sb.append(',');
        }
        return sb.toString();
    }

    public static void main(String[] args) {
        int n = 100_000;

        long t1 = System.currentTimeMillis();
        buildSlow(n);
        System.out.println("Slow: " + (System.currentTimeMillis() - t1) + " ms");
        // Typically several seconds

        long t2 = System.currentTimeMillis();
        buildFast(n);
        System.out.println("Fast: " + (System.currentTimeMillis() - t2) + " ms");
        // Typically < 20 ms

        // Reverse using StringBuilder
        String reversed = new StringBuilder("Hello, World!").reverse().toString();
        System.out.println(reversed); // !dlroW ,olleH
    }
}

