import java.util.Arrays;

public class StringComparison {
    public static void main(String[] args) {
        String a = new String("hello");
        String b = new String("hello");
        String c = "hello";
        String d = "hello";

        System.out.println(a == b);       // false — different objects
        System.out.println(a == c);       // false — a is not the pool instance
        System.out.println(c == d);       // true  — both point to the same pool entry
        System.out.println(a.equals(b));  // true  — content is the same

        System.out.println("Apple".equals("banana"));           // false
        System.out.println("Apple".equalsIgnoreCase("apple"));  // true

        // compareTo: negative = comes before, 0 = equal, positive = comes after
        String[] fruits = {"banana", "apple", "cherry"};
        System.out.println(fruits[0].compareTo(fruits[1])); // positive (b > a)
        System.out.println(fruits[1].compareTo(fruits[2])); // negative (a < c)
        Arrays.sort(fruits);
        System.out.println(Arrays.toString(fruits)); // [apple, banana, cherry]
    }
}

