public class StringIntern {
    public static void main(String[] args) {
        String s1 = new String("java");
        String s2 = new String("java");

        System.out.println(s1 == s2);      // false — different heap objects
        System.out.println(s1.equals(s2)); // true  — same content

        String i1 = s1.intern();
        String i2 = s2.intern();
        System.out.println(i1 == i2); // true — both point to the same pool entry

        String literal = "java";
        System.out.println(literal == i1); // true — literal was already the pool entry

        // Simulated deduplication via intern
        String[] raw = {"status:OK", "status:OK", "status:ERROR", "status:OK"};
        String[] deduped = new String[raw.length];
        for (int i = 0; i < raw.length; i++) {
            deduped[i] = raw[i].intern(); // collapses duplicates
        }
        System.out.println(deduped[0] == deduped[1]); // true — same object!
        System.out.println(deduped[0] == deduped[2]); // false — different content
    }
}

