public class PalindromeCheck {

    static String reverse(String s) {
        return new StringBuilder(s).reverse().toString();
    }

    static boolean isPalindrome(String s) {
        // Two-pointer approach — O(n/2) comparisons, O(1) space
        int left = 0, right = s.length() - 1;
        while (left < right) {
            if (s.charAt(left) != s.charAt(right)) return false;
            left++;
            right--;
        }
        return true;
    }

    static boolean isPalindromeIgnoringNonAlpha(String s) {
        // Remove non-letters, lowercase, then two-pointer
        String cleaned = s.replaceAll("[^a-zA-Z]", "").toLowerCase();
        return isPalindrome(cleaned);
    }

    public static void main(String[] args) {
        System.out.println(reverse("Hello"));       // olleH
        System.out.println(isPalindrome("racecar")); // true
        System.out.println(isPalindrome("hello"));   // false
        System.out.println(isPalindromeIgnoringNonAlpha("A man a plan a canal Panama")); // true
        System.out.println(isPalindromeIgnoringNonAlpha("race a car")); // false
    }
}

