import java.util.*;

public class StringAlgorithms {

    static int countVowels(String s) {
        int count = 0;
        for (char c : s.toLowerCase().toCharArray()) {
            if ("aeiou".indexOf(c) >= 0) count++;
        }
        return count;
    }

    static Map<String, Integer> wordFrequency(String sentence) {
        Map<String, Integer> freq = new LinkedHashMap<>();
        for (String word : sentence.toLowerCase().split("\\s+")) {
            word = word.replaceAll("[^a-z]", ""); // strip punctuation
            if (!word.isEmpty()) {
                freq.put(word, freq.getOrDefault(word, 0) + 1);
            }
        }
        return freq;
    }

    static boolean isAnagram(String s1, String s2) {
        if (s1.length() != s2.length()) return false;
        int[] freq = new int[26];
        for (char c : s1.toLowerCase().toCharArray()) freq[c - 'a']++;
        for (char c : s2.toLowerCase().toCharArray()) freq[c - 'a']--;
        for (int f : freq) if (f != 0) return false;
        return true;
    }

    static char mostFrequent(String s) {
        Map<Character, Integer> freq = new LinkedHashMap<>();
        for (char c : s.toCharArray()) {
            if (c != ' ') freq.put(c, freq.getOrDefault(c, 0) + 1);
        }
        return Collections.max(freq.entrySet(),
            Comparator.comparingInt(Map.Entry::getValue)).getKey();
    }

    public static void main(String[] args) {
        System.out.println(countVowels("Hello World"));     // 3
        System.out.println(wordFrequency("to be or not to be"));
        // {to=2, be=2, or=1, not=1}
        System.out.println(isAnagram("listen", "silent"));  // true
        System.out.println(isAnagram("hello", "world"));   // false
        System.out.println(mostFrequent("aabbbcccc"));      // c
    }
}

