    private static final String OCTET =
        "(25[0-5]|2[0-4]\\d|[01]?\\d{1,2})";
    private static final Pattern IPV4_PATTERN =
        Pattern.compile("^" + OCTET + "\\." + OCTET + "\\." + OCTET + "\\." + OCTET + "$");

    static boolean isValidEmail(String email) {
        return EMAIL_PATTERN.matcher(email).matches();
    }

    static List<Integer> extractIntegers(String text) {
        List<Integer> results = new ArrayList<>();
        Matcher m = INT_PATTERN.matcher(text);
        while (m.find()) results.add(Integer.parseInt(m.group()));
        return results;
    }

    static boolean isValidIPv4(String ip) {
        return IPV4_PATTERN.matcher(ip).matches();
    }

    public static void main(String[] args) {
        System.out.println(isValidEmail("alice@example.com"));   // true
        System.out.println(isValidEmail("alice@.com"));          // false
        System.out.println(isValidEmail("bad-email"));           // false
        System.out.println(extractIntegers("Temperature -5, Humidity 80, Pressure 1013"));
        // [-5, 80, 1013]
        System.out.println(isValidIPv4("192.168.0.1"));  // true
        System.out.println(isValidIPv4("999.0.0.1"));   // false — 999 > 255
        System.out.println(isValidIPv4("192.168.0"));   // false — only 3 octets
    }
}
